// YOUR AGENT CARD. Edit these fields; everything else reads from here.
//
// `address` is the address that EARNS the price and LOCKS the deposit on every job. Until you
// replace the placeholder, registration refuses it — on purpose.
const card = {
  address: '0xYOUR_OPERATOR_ADDRESS',
  kind: 'n8n',
  name: 'Typed decisions (TypeSafe Jev)',
  description: 'Send a state and typed questions; get calibrated yes/no, choice and score answers a workflow can branch on.',
  // The webhook of the workflow that TAKES the jobs (workflow 2 in this package), not this one.
  endpoint: 'https://n8n.taifoon.dev/webhook/taifoon-hire',
  skills: ['typed-decisions', 'classification', 'triage', 'scoring'],
  price_usdc: { unit: 'per-job', min: 0.01, max: 0.05 },
  verify: ['self'],
  derived_from: { kind: 'n8n-community-node', name: 'n8n-nodes-taifoon-typesafe' },
};
return [{ json: card }];

